        Assert.AreEqual(150m, calc.CalculateDiscount(1000m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelowThousand_Returns10Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(99.99m, calc.CalculateDiscount(999.9m));
    }

    [TestMethod]
    public void CalculateDiscount_ExactlyAtFiveHundred_Returns10Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(50m, calc.CalculateDiscount(500m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelowFiveHundred_Returns5Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(24.995m, calc.CalculateDiscount(499.9m));
    }

    [TestMethod]
    public void CalculateDiscount_ExactlyAtHundred_Returns5Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(5m, calc.CalculateDiscount(100m));
    }

    [TestMethod]
    public void CalculateDiscount_JustBelowHundred_ReturnsZero()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateDiscount(99.99m));
    }

    [TestMethod]
    public void CalculateDiscount_Zero_ReturnsZero()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateDiscount(0m));
    }

    // -- CalculateShipping tests --

    [TestMethod]
    public void CalculateShipping_LargeOrder_FreeShipping()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateShipping(500m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_ExactlyAt250_NotFree()
    {
        var calc = new DiscountCalculator();
        // orderTotal == 250 is NOT > 250, so shipping is charged
        var cost = calc.CalculateShipping(250m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

    [TestMethod]
    public void CalculateShipping_JustAbove250_FreeShipping()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateShipping(250.01m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_SmallOrder_ReturnsBaseCost()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(6.00m, calc.CalculateShipping(50m, 2.0, false));
    }

    [TestMethod]
    public void CalculateShipping_HeavyItem_AddsHeavyFee()
    {
        var calc = new DiscountCalculator();
        // 5 + (11 * 0.5) + 15 = 25.50
        Assert.AreEqual(25.50m, calc.CalculateShipping(50m, 11.0, false));
    }

    [TestMethod]
    public void CalculateShipping_ExactlyAt10kg_NoHeavyFee()
    {
        var calc = new DiscountCalculator();
        // 5 + (10 * 0.5) = 10.00 (10kg is NOT > 10)
        Assert.AreEqual(10.00m, calc.CalculateShipping(50m, 10.0, false));
    }

    [TestMethod]
    public void CalculateShipping_Express_Adds50PercentSurcharge()
    {
        var calc = new DiscountCalculator();
        // base = 5 + (2 * 0.5) = 6, express = 6 * 1.5 = 9
        Assert.AreEqual(9.00m, calc.CalculateShipping(50m, 2.0, true));
    }

    [TestMethod]
    public void CalculateShipping_ExpressAndHeavy_BothApplied()
    {
        var calc = new DiscountCalculator();
        // base = 5 + (11 * 0.5) + 15 = 25.50, express = 25.50 * 1.5 = 38.25
        Assert.AreEqual(38.25m, calc.CalculateShipping(50m, 11.0, true));
    }

    [TestMethod]
    public void CalculateShipping_ZeroWeight_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(50m, 0, false));
    }

    [TestMethod]
    public void CalculateShipping_ZeroOrderTotal_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(0m, 2.0, false));
    }

    // -- ApplyCoupon tests --

    [TestMethod]
    public void ApplyCoupon_Save10_Applies10Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(90m, calc.ApplyCoupon(100m, "SAVE10"));
    }

    [TestMethod]
    public void ApplyCoupon_Save20_Applies20Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(80m, calc.ApplyCoupon(100m, "SAVE20"));
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_SubtractsFive()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(95m, calc.ApplyCoupon(100m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_Flat50_SubtractsFifty()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(150m, calc.ApplyCoupon(200m, "FLAT50"));
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ReturnsOriginalTotal()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(100m, calc.ApplyCoupon(100m, "BOGUS"));
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(90m, calc.ApplyCoupon(100m, "save10"));
    }

    [TestMethod]
    public void ApplyCoupon_FloorAtOneDollar()
    {
        var calc = new DiscountCalculator();
        // FLAT50 on a $2 total: 2 - 50 = -48, clamped to 1.00
        Assert.AreEqual(1.00m, calc.ApplyCoupon(2m, "FLAT50"));
    }

    [TestMethod]
    public void ApplyCoupon_ExactlyAtFloor_ReturnsOne()
    {
        var calc = new DiscountCalculator();
        // FLAT5 on a $6 total: 6 - 5 = 1.00, exactly the floor
        Assert.AreEqual(1.00m, calc.ApplyCoupon(6m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_JustAboveFloor()
    {
        var calc = new DiscountCalculator();
        // FLAT5 on a $6.01 total: 6.01 - 5 = 1.01, just above floor
        Assert.AreEqual(1.01m, calc.ApplyCoupon(6.01m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_NullCoupon_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentNullException>(
            () => calc.ApplyCoupon(100m, null!));
    }

    [TestMethod]
    public void ApplyCoupon_ZeroTotal_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.ApplyCoupon(0m, "SAVE10"));
    }
}

